
CREATE TABLE a (
	id INT NOT NULL AUTO_INCREMENT,
	name VARCHAR(50) NOT NULL,
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE b (
	id INT NOT NULL AUTO_INCREMENT,
	a_id INT NOT NULL,
	PRIMARY KEY (id),
	KEY idx_b_a (a_id),
	CONSTRAINT fk_b_a FOREIGN KEY (a_id) REFERENCES a (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
